func (q *Queries) SetRequestImportedLab(ctx context.Context, arg SetRequestImportedLabParams) error {
	_, err := q.db.ExecContext(ctx, setRequestImportedLab,
		arg.ImportedLabID,
		arg.UpdatedAt,
		arg.ID,
		arg.UserID,
	)
	return err
}

const updateService = `-- name: UpdateService :exec
UPDATE ` + "`" + `partner_lab_services` + "`" + ` SET ` + "`" + `code` + "`" + ` = ?, ` + "`" + `kind` + "`" + ` = ?, ` + "`" + `title` + "`" + ` = ?, ` + "`" + `description` + "`" + ` = ?, ` + "`" + `partner_name` + "`" + ` = ?,
  ` + "`" + `partner_code` + "`" + ` = ?, ` + "`" + `is_active` + "`" + ` = ?, ` + "`" + `sort_order` + "`" + ` = ?, ` + "`" + `updated_at` + "`" + ` = ?
WHERE id = ?
`

type UpdateServiceParams struct {
	Code        string
	Kind        string
	Title       string
	Description sql.NullString
	PartnerName string
	PartnerCode string
	IsActive    bool
	SortOrder   int32
	UpdatedAt   sql.NullTime
	ID          uint64
}

func (q *Queries) UpdateService(ctx context.Context, arg UpdateServiceParams) error {
	_, err := q.db.ExecContext(ctx, updateService,
		arg.Code,
		arg.Kind,
		arg.Title,
		arg.Description,
		arg.PartnerName,
		arg.PartnerCode,
		arg.IsActive,
		arg.SortOrder,
		arg.UpdatedAt,
		arg.ID,
	)
	return err
}
